@contextmanager
def mock_calls(obj, name):
    original = getattr(obj, name)
    calls = []

    def spy(*args):
        calls.append(args)
        return original(*args)

    setattr(obj, name, spy)
    try:
        yield calls
    finally:
        setattr(obj, name, original)

