class Connection:
    def __init__(self, log):
        self.log = log
        self.closed = True

    def __enter__(self):
        self.log.append("connect")
        self.closed = False
        return self

    def execute(self, sql):
        if self.closed:
            raise RuntimeError("соединение закрыто")
        self.log.append(sql)

    def __exit__(self, *args):
        self.log.append("close")
        self.closed = True
        return False

