from contextlib import contextmanager


class Pool:
    def __init__(self, size):
        self.free = [f"conn{i}" for i in range(size)]

    @contextmanager
    def connection(self):
        if not self.free:
            raise RuntimeError("пул исчерпан")
        conn = self.free.pop()
        try:
            yield conn
        finally:
            self.free.append(conn)

